// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.memoryimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport java.time.Instant/** * NOUS — Memory interface (Brain's view). * * Brain uses this interface to access the memory system. Module 3 * (:feature:memory) provides the implementation. Brain NEVER touches Room * directly — only via this interface. * * This indirection allows: *   - Brain to compile without depending on Room (faster build) *   - Memory backend to change (Room → vector DB) without breaking Brain *   - Tests to swap in [FakeMemoryInterface] easily * * @see <a href="docs/spec/module2-spec-review.pdf">§3.7 MemoryInterface</a> */interface MemoryInterface {    /**     * Get top-K relevant memories for a query (semantic search).     *     * @param query the search query (typically the user's input)     * @param k maximum number of memories to return (default 5)     * @return list of memories sorted by relevance (most relevant first)     */    suspend fun recall(query: String, k: Int = 5): Result<List<Memory>>    /**     * Store a new memory (called by post-processing after each interaction).     *     * @param memory the memory to store     * @return the stored memory's ID     */    suspend fun store(memory: Memory): Result<MemoryId>    /**     * Get user facts (e.g., "user's name is Roshan", "user is a software engineer").     *     * @return list of known facts about the user     */    suspend fun getUserFacts(): Result<List<UserFact>>    /**     * Get active KG (Knowledge Graph) entities mentioned in the active session.     * Used for coreference resolution (Fixes #26).     *     * @param sessionId the active conversation session     * @return list of entities mentioned in this session     */    suspend fun getActiveEntities(sessionId: SessionId): Result<List<KgEntity>>    /**     * Forget a memory (user-initiated, e.g., from Memory Browser).     *     * @param memoryId the memory to forget     * @return success or failure     */    suspend fun forget(memoryId: MemoryId): Result<Unit>    /**     * Forget all memories (factory reset within app).     *     * @return success or failure     */    suspend fun forgetAll(): Result<Unit>}/** Memory ID — opaque. */@JvmInlinevalue class MemoryId(val value: Long)/** * A stored memory. * * @see <a href="docs/spec/module2-spec-review.pdf">§3.7 Memory</a> */data class Memory(    val id: MemoryId? = null,    val type: MemoryType,    val content: String,    val timestamp: Instant,    val importance: Float,  // 0.0-1.0    val tags: Set<String>,    val embedding: FloatArray? = null,  // 384-dim MiniLM embedding    val correlationId: CorrelationId? = null,  // original request that created it    val sessionId: SessionId? = null,) {    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (javaClass != other?.javaClass) return false        val o = other as? Memory ?: return false        if (id != o.id) return false        if (type != o.type) return false        if (content != o.content) return false        if (timestamp != o.timestamp) return false        if (importance != o.importance) return false        if (tags != o.tags) return false        if (correlationId != o.correlationId) return false        if (sessionId != o.sessionId) return false        // Embedding arrays — use contentEquals        if (embedding != null) {            if (o.embedding == null) return false            if (!embedding.contentEquals(o.embedding)) return false        } else if (o.embedding != null) return false        return true    }    override fun hashCode(): Int {        var result = id?.hashCode() ?: 0        result = 31 * result + type.hashCode()        result = 31 * result + content.hashCode()        result = 31 * result + timestamp.hashCode()        result = 31 * result + importance.hashCode()        result = 31 * result + tags.hashCode()        result = 31 * result + (embedding?.contentHashCode() ?: 0)        result = 31 * result + (correlationId?.hashCode() ?: 0)        result = 31 * result + (sessionId?.hashCode() ?: 0)        return result    }}enum class MemoryType {    /** Working Memory — last 10 turns, in-memory, session-only (Strategy §3). */    WORKING,    /** Specific event ("user asked me to call mom at 3 PM"). 30-day retention. */    EPISODIC,    /** General fact ("user's mother's name is Sunita"). Permanent. */    SEMANTIC,    /** How-to / skill knowledge ("to send SMS, use SmsSkill"). Permanent. */    PROCEDURAL,    /** Affective association ("user was happy when discussing Goa trip"). 90-day decay with Ebbinghaus curve. */    EMOTIONAL,}/** A known fact about the user. */data class UserFact(    val key: String,         // e.g., "name", "occupation", "favorite_color"    val value: String,       // e.g., "Roshan", "Software Engineer", "blue"    val confidence: Float,   // 0.0-1.0    val source: FactSource,  // how we learned this    val learnedAt: Instant,)enum class FactSource {    USER_EXPLICIT,    // user told us directly    USER_IMPLICIT,    // inferred from behavior    MEMORY_INFERENCE, // inferred from episodic memories    PERSONA_DEFAULT,  // default value}/** Knowledge Graph entity (for coreference). */data class KgEntity(    val id: String,    val type: EntityType,    val canonicalName: String,    val aliases: Set<String>,    val mentionedInSession: Boolean,)enum class EntityType {    PERSON,    ORGANIZATION,    LOCATION,    DATE,    TIME,    DURATION,    APP,    DEVICE,    CONCEPT,}